SELECT tags, timestamp, any(value) AS value FROM (SELECT if(arrayStringConcat([tupleElement(arrayFirst(tag -> tag.1 = 'job', arrayPushBack(label_child.tags, tuple('job', ''))), 2), tupleElement(arrayFirst(tag -> tag.1 = 'instance', arrayPushBack(label_child.tags, tuple('instance', ''))), 2)], '-') = '', arrayFilter(tag -> tag.1 != 'combined', label_child.tags), arraySort(tag -> tag.1, arrayPushBack(arrayFilter(tag -> tag.1 != 'combined', label_child.tags), tuple('combined', arrayStringConcat([tupleElement(arrayFirst(tag -> tag.1 = 'job', arrayPushBack(label_child.tags, tuple('job', ''))), 2), tupleElement(arrayFirst(tag -> tag.1 = 'instance', arrayPushBack(label_child.tags, tuple('instance', ''))), 2)], '-'))))) AS tags, label_child.timestamp AS timestamp, label_child.value AS value FROM (SELECT series.tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
    SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {label_child_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({label_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({label_child_required_end_ms:Int64})
) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({label_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({label_child_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags) AS label_child) AS label_rows GROUP BY tags, timestamp HAVING throwIf(count() > 1, 'vector cannot contain metrics with the same labelset') = 0 ORDER BY tags ASC, timestamp ASC
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
